import { useId, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../api/client';
import { messageOf } from '../lib/errors';

/**
 * `Import CSV` dialog for REQ-1-3-1 (Issue #3 decision D-A6).
 *
 * The file is read client-side as UTF-8 text and posted as JSON to
 * `POST /api/workbooks/import`. On success the editor opens with the complete
 * imported worksheet; on failure the dialog stays open with the chosen file and
 * shows the server's exact message (`Invalid CSV file format. Import failed.`),
 * so the home page list never shows a partial record.
 */
export function ImportCsvDialog({ onClose }: { onClose: () => void }) {
  const navigate = useNavigate();
  const titleId = useId();
  const fileInputId = useId();
  const [file, setFile] = useState<File | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const confirm = async () => {
    if (!file) {
      setError('Choose a CSV file first.');
      return;
    }
    setBusy(true);
    setError(null);
    try {
      const csv = await file.text();
      const created = await api.importWorkbookCsv(file.name, csv);
      navigate(`/workbook/${encodeURIComponent(created.id)}`);
    } catch (caught) {
      setError(messageOf(caught));
      setBusy(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="sheet-dialog w-full max-w-md"
      >
        <h2 id={titleId} className="mb-4 text-lg font-medium text-sheet-text">
          Import CSV
        </h2>
        <label htmlFor={fileInputId} className="mb-1 block text-sm text-sheet-text">
          CSV file
        </label>
        <input
          id={fileInputId}
          type="file"
          accept=".csv,text/csv"
          onChange={(event) => {
            setFile(event.target.files?.[0] ?? null);
            setError(null);
          }}
          className="mb-4 block w-full text-sm text-sheet-text"
        />
        {error ? (
          <p role="alert" className="mb-3 text-sm text-sheet-danger">
            {error}
          </p>
        ) : null}
        <div className="flex items-center justify-end gap-2">
          <button type="button" className="sheet-button" onClick={onClose}>
            Cancel
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => {
              void confirm();
            }}
            className="rounded bg-sheet-accent px-4 py-1.5 text-sm text-white disabled:opacity-60"
          >
            Confirm import
          </button>
        </div>
      </div>
    </div>
  );
}

